mapper.insert:
/* setFollow */
INSERT INTO TB_FOLLOW (
            USER_NUMB
          , FLOW_NUMB
          , REGI_DATE
) VALUES (  #{userNumb}
          , #{flowNumb}
          , CURRENT_TIMESTAMP
) AS NEW
ON DUPLICATE KEY UPDATE
       USER_NUMB = NEW.USER_NUMB

mapper.delete:
DELETE /* delFollow */
  FROM TB_FOLLOW
 WHERE USER_NUMB = #{userNumb}
   AND FLOW_NUMB = #{flowNumb}

mapper.select:
SELECT /* dupLike */
       COUNT(*)
  FROM TB_LIKEXX
 WHERE USER_NUMB = #{userNumb}
   AND TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}

mapper.insert:
/* setLike */
INSERT INTO TB_LIKEXX (
